 public sealed class DiffMap:FrameworkElement {
  public MainWindow Owner;protected override void OnRender(DrawingContext dc){base.OnRender(dc);dc.DrawRectangle(MainWindow.Brush(Owner.Dark?"#263140":"#E2E8F0"),null,new Rect(0,0,ActualWidth,ActualHeight));if(Owner.Result==null)return;int n=Owner.Result.Rows.Count;foreach(var r in Owner.VisibleChanges){string color=r.Kind==ChangeKind.Added?"#16A36D":r.Kind==ChangeKind.Removed?"#D65C72":"#D1A039";dc.DrawRectangle(MainWindow.Brush(color),null,new Rect(2,r.Index*ActualHeight/Math.Max(1,n),Math.Max(1,ActualWidth-4),Math.Max(3,ActualHeight/Math.Max(1,n))));}}
  protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){if(Owner.Result==null)return;int index=(int)(e.GetPosition(this).Y/Math.Max(1,ActualHeight)*Owner.Result.Rows.Count);var row=Owner.VisibleChanges.OrderBy(r=>Math.Abs(r.Index-index)).FirstOrDefault();if(row!=null)Owner.Go(row);}
 }
