  TextBox FileBox(Grid parent,bool left,int col){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var label=new TextBlock{Text=left?"左侧 · 原文档":"右侧 · 对比文档",FontWeight=FontWeights.SemiBold,Margin=new Thickness(8,0,12,0),VerticalAlignment=VerticalAlignment.Center};label.SetResourceReference(TextBlock.ForegroundProperty,left?"LeftBrush":"RightBrush");grid.Children.Add(label);var t=new TextBox{MinHeight=29,Padding=new Thickness(6,3,6,3),VerticalContentAlignment=VerticalAlignment.Center,AllowDrop=true,ToolTip="输入完整路径，或拖入 Word 文件"};Grid.SetColumn(t,1);grid.Children.Add(t);t.PreviewDrop+=(s,e)=>{var files=e.Data.GetData(DataFormats.FileDrop) as string[];if(files!=null&&files.Length>0)t.Text=files[0];e.Handled=true;};t.KeyDown+=async(s,e)=>{if(e.Key==Key.Enter)await Run();};var button=Btn("浏览…",()=>Browse(left));Grid.SetColumn(button,2);grid.Children.Add(button);var border=new Border{Child=grid,BorderBrush=Brush("#CBD5E1"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(4),Padding=new Thickness(3)};border.SetResourceReference(Border.BorderBrushProperty,"BorderBrush");Grid.SetColumn(border,col);parent.Children.Add(border);return t;}
  const string Filter="Word 文档 (*.docx;*.docm;*.doc)|*.docx;*.docm;*.doc|其他文档 (*.rtf;*.odt;*.txt)|*.rtf;*.odt;*.txt|所有文件 (*.*)|*.*";
  void Browse(bool left){var dialog=new OpenFileDialog{Filter=Filter,Title=left?"选择左侧原文档":"选择右侧对比文档",CheckFileExists=true};if(dialog.ShowDialog(this)==true)(left?leftPath:rightPath).Text=dialog.FileName;}
  async void OpenPair(){if(busy)return;var dialog=new OpenFileDialog{Filter=Filter,Multiselect=true,Title="同时选择两个文档：第一个为左侧，第二个为右侧"};if(dialog.ShowDialog(this)==true){if(dialog.FileNames.Length!=2){MessageBox.Show(this,"请一次选择两个文件。","选择文档");return;}leftPath.Text=dialog.FileNames[0];rightPath.Text=dialog.FileNames[1];await Run();}}
  void OpenSource(bool left){string p=(left?leftPath:rightPath).Text;if(File.Exists(p))Process.Start(new ProcessStartInfo(p){UseShellExecute=true});}
  CompareOptions Options(){return new CompareOptions{Formatting=format.IsChecked==true,IgnoreSpace=space.IsChecked==true,IgnoreCase=caseBox.IsChecked==true,Extras=extras.IsChecked==true,Highlight=(HighlightLevel)highlight.SelectedIndex};}
  public async Task Run(){if(busy||!ConfirmReview())return;string a=leftPath.Text.Trim().Trim('"'),b=rightPath.Text.Trim().Trim('"');if(!File.Exists(a)||!File.Exists(b)){MessageBox.Show(this,"请先选择两份存在的 Word 文档。","无法开始对比",MessageBoxButton.OK,MessageBoxImage.Information);return;}
   busy=true;compare.IsEnabled=false;progress.Visibility=Visibility.Visible;status.Text="正在读取并比较文档…";cancel=new CancellationTokenSource();var options=Options();var clock=Stopwatch.StartNew();try{Result=await Task.Run(()=>DiffEngine.Compare(DocxReader.Load(a,cancel.Token),DocxReader.Load(b,cancel.Token),options,cancel.Token));if(!IsLoaded)return;reviewDirty=false;DiffEngine.Rehighlight(Result,(HighlightLevel)highlight.SelectedIndex);Refresh();status.Text="比较完成 · "+clock.Elapsed.TotalSeconds.ToString("0.00")+" 秒 · 左 "+Result.Left.Units.Count+" 项 / 右 "+Result.Right.Units.Count+" 项";var notes=Result.Left.Notes.Concat(Result.Right.Notes).Distinct().ToArray();if(notes.Length>0){status.ToolTip=string.Join("\n",notes);status.Text+=" · 有读取说明（悬停查看）";}else status.ToolTip="内容对齐视图，不复刻 Word 原分页；输入文件只读。";}
   catch(OperationCanceledException){status.Text="比较已取消。";}catch(Exception ex){Result=null;Refresh();status.Text="比较失败";if(!closePending)MessageBox.Show(this,ex.Message,"Word_Compare 读取失败",MessageBoxButton.OK,MessageBoxImage.Error);}finally{busy=false;compare.IsEnabled=true;progress.Visibility=Visibility.Collapsed;if(closePending)Close();}}
  public void Refresh(){if(!ready)return;if(Result==null){list.ItemsSource=null;changes.ItemsSource=null;summary.Text="";reviewSummary.Text="";empty.Visibility=Visibility.Visible;return;}var selected=list.SelectedItem as DisplayRow;visible=ReviewTools.Filter(Result,typeFilter.SelectedIndex,stateFilter.SelectedIndex,only.IsChecked==true).Select(r=>new DisplayRow{Row=r,Owner=this}).ToList();list.ItemsSource=visible;changes.ItemsSource=ReviewTools.Sort(VisibleChanges,sortOrder.SelectedIndex);summary.Text=Reports.Summary(Result);reviewSummary.Text="显示 "+VisibleChanges.Count()+" / "+Result.Changes+" 项差异\n"+ReviewTools.Summary(Result)+(reviewDirty?"\n审核状态尚未保存":"");empty.Visibility=visible.Count==0?Visibility.Visible:Visibility.Collapsed;if(visible.Count==0)empty.Text=Result.Changes==0?"两份文档在当前比较选项下相同":"当前视图没有内容";map.InvalidateVisual();if(selected!=null)Go(selected.Row);}
  public void Go(DiffRow row){var item=visible.FirstOrDefault(v=>v.Row==row);if(item==null)return;list.SelectedItem=item;list.ScrollIntoView(item);}
  void Navigate(int direction){if(Result==null)return;var current=list.SelectedItem as DisplayRow;int at=current==null?(direction>0?-1:Result.Rows.Count):current.Row.Index;var candidates=VisibleChanges.ToList();if(candidates.Count==0)return;DiffRow target=direction>0?candidates.FirstOrDefault(r=>r.Index>at):candidates.LastOrDefault(r=>r.Index<at);Go(target??(direction>0?candidates[0]:candidates[candidates.Count-1]));}
  void Find(){if(Result==null||search.Text.Length==0)return;var current=list.SelectedItem as DisplayRow;int start=current==null?-1:current.Row.Index;var hits=visible.Where(v=>((v.Row.Left==null?"":v.Row.Left.Text)+"\n"+(v.Row.Right==null?"":v.Row.Right.Text)).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();if(hits.Count==0){status.Text="没有找到："+search.Text;return;}Go((hits.FirstOrDefault(v=>v.Row.Index>start)??hits[0]).Row);status.Text="找到 "+hits.Count+" 项匹配；回车继续查找。";}
  async void Export(){if(Result==null||busy)return;var dialog=new SaveFileDialog{Filter="Word 对比报告 (*.docx)|*.docx|HTML 双栏报告（含图片）(*.html)|*.html|CSV 差异清单 (*.csv)|*.csv|PDF 对比报告 (*.pdf)|*.pdf|JSON 完整审核记录 (*.json)|*.json",FileName="Word_Compare对比报告.docx",InitialDirectory=Path.GetDirectoryName(Result.Left.Path),OverwritePrompt=true};if(dialog.ShowDialog(this)!=true)return;try{busy=true;progress.Visibility=Visibility.Visible;status.Text="正在导出报告…";bool json=Path.GetExtension(dialog.FileName).Equals(".json",StringComparison.OrdinalIgnoreCase);var result=json?Result:new Comparison{Left=Result.Left,Right=Result.Right,Options=Result.Options,Rows=visible.Select(v=>v.Row).ToList()};await Task.Run(()=>Reports.Save(result,dialog.FileName,false));if(json){reviewDirty=false;Refresh();}status.Text=(json?"完整审核记录已保存：":"当前视图报告已保存：")+dialog.FileName;}catch(Exception ex){if(!closePending)MessageBox.Show(this,ex.Message,"报告导出失败",MessageBoxButton.OK,MessageBoxImage.Error);}finally{busy=false;progress.Visibility=Visibility.Collapsed;if(closePending)Close();}}
  ComboBox FilterCombo(string[] labels){var combo=new ComboBox{ItemsSource=labels,SelectedIndex=0,Margin=new Thickness(3,2,3,3),MinHeight=29};combo.SelectionChanged+=(s,e)=>{if(ready)Refresh();};return combo;}
  void MarkReview(ReviewState state){if(Result==null||busy)return;var selected=list.SelectedItem as DisplayRow;if(selected==null||selected.Row.Kind==ChangeKind.Same){status.Text="请先在双栏或差异列表中选择一项差异。";return;}var row=selected.Row;if(row.Review==state)return;row.Review=state;reviewDirty=true;Refresh();if(!visible.Any(v=>v.Row==row)){var next=VisibleChanges.FirstOrDefault(r=>r.Index>row.Index)??VisibleChanges.FirstOrDefault();if(next!=null)Go(next);}status.Text="第 "+(row.Index+1)+" 项已标记为"+row.ReviewText+"；原文档未修改，请保存审核记录。";}
  bool SaveReview(){if(Result==null||busy)return false;var dialog=new SaveFileDialog{Filter="JSON 完整审核记录 (*.json)|*.json",FileName="Word_Compare审核记录.json",InitialDirectory=Path.GetDirectoryName(Result.Left.Path),OverwritePrompt=true};if(dialog.ShowDialog(this)!=true)return false;try{ReviewStore.Save(Result,dialog.FileName);reviewDirty=false;Refresh();status.Text="完整审核记录已保存："+dialog.FileName;return true;}catch(Exception e){MessageBox.Show(this,e.Message,"保存审核失败",MessageBoxButton.OK,MessageBoxImage.Error);return false;}}
  bool ConfirmReview(){if(!reviewDirty)return true;var choice=MessageBox.Show(this,"当前审核意见尚未保存。是否先保存 JSON 审核记录？\n选择“否”将放弃本次尚未保存的意见。","Word_Compare",MessageBoxButton.YesNoCancel,MessageBoxImage.Question);if(choice==MessageBoxResult.Yes)return SaveReview();if(choice==MessageBoxResult.No){reviewDirty=false;return true;}return false;}
  void LoadReview(){if(Result==null||busy)return;var dialog=new OpenFileDialog{Filter="JSON 审核记录 (*.json)|*.json",CheckFileExists=true};if(dialog.ShowDialog(this)!=true||!ConfirmReview())return;try{int count=ReviewStore.Load(Result,dialog.FileName);reviewDirty=false;Refresh();status.Text="已载入 "+count+" 项审核意见；文档内容和比较规则校验通过。";}catch(Exception e){MessageBox.Show(this,e.Message,"载入审核失败",MessageBoxButton.OK,MessageBoxImage.Error);}}
  void ControlStyles(){
   var button=new Style(typeof(Button));button.Setters.Add(new Setter(Control.BackgroundProperty,Brush(Dark?"#2A3443":"#F2F4F6")));button.Setters.Add(new Setter(Control.ForegroundProperty,Brush(Text)));button.Setters.Add(new Setter(Control.BorderBrushProperty,Brush(Line)));button.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(1)));
   var template=new ControlTemplate(typeof(Button));var frame=new FrameworkElementFactory(typeof(Border));frame.Name="Frame";frame.SetValue(Border.CornerRadiusProperty,new CornerRadius(3));frame.SetBinding(Border.BackgroundProperty,new Binding("Background"){RelativeSource=RelativeSource.TemplatedParent});frame.SetBinding(Border.BorderBrushProperty,new Binding("BorderBrush"){RelativeSource=RelativeSource.TemplatedParent});frame.SetBinding(Border.BorderThicknessProperty,new Binding("BorderThickness"){RelativeSource=RelativeSource.TemplatedParent});frame.SetBinding(Border.PaddingProperty,new Binding("Padding"){RelativeSource=RelativeSource.TemplatedParent});var presenter=new FrameworkElementFactory(typeof(ContentPresenter));presenter.SetValue(FrameworkElement.HorizontalAlignmentProperty,HorizontalAlignment.Center);presenter.SetValue(FrameworkElement.VerticalAlignmentProperty,VerticalAlignment.Center);presenter.SetBinding(ContentPresenter.ContentProperty,new Binding("Content"){RelativeSource=RelativeSource.TemplatedParent});presenter.SetBinding(ContentPresenter.ContentTemplateProperty,new Binding("ContentTemplate"){RelativeSource=RelativeSource.TemplatedParent});frame.AppendChild(presenter);template.VisualTree=frame;
   var hover=new Trigger{Property=UIElement.IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(UIElement.OpacityProperty,.83));template.Triggers.Add(hover);var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(UIElement.OpacityProperty,.5));template.Triggers.Add(disabled);button.Setters.Add(new Setter(Control.TemplateProperty,template));Resources[typeof(Button)]=button;
   var text=new Style(typeof(TextBox));text.Setters.Add(new Setter(Control.BackgroundProperty,Brush(Surface)));text.Setters.Add(new Setter(Control.ForegroundProperty,Brush(Text)));text.Setters.Add(new Setter(Control.BorderBrushProperty,Brush(Line)));Resources[typeof(TextBox)]=text;
   var menus=new Style(typeof(MenuItem));menus.Setters.Add(new Setter(Control.ForegroundProperty,Brush(Text)));menus.Setters.Add(new Setter(Control.BackgroundProperty,Brush(Surface)));Resources[typeof(MenuItem)]=menus;
   Resources[typeof(ToggleButton)]=Appearance.ToggleStyle();Resources[typeof(ComboBox)]=Appearance.ZoomStyle();Resources[typeof(ComboBoxItem)]=Appearance.ZoomItemStyle();
  }
  void Theme(){if(!ready)return;Background=Brush(Dark?"#11161D":"#F5F7FA");Foreground=Brush(Text);Resources["SurfaceBrush"]=Brush(Surface);Resources["TextBrush"]=Brush(Text);Resources["BorderBrush"]=Brush(Line);Resources["AccentBrush"]=Brush(Dark?"#176F65":"#087F72");Resources["RightBrush"]=Brush(Dark?"#87DABB":"#087F48");Resources["LeftBrush"]=Brush(Dark?"#F1A7B4":"#99394A");Resources["HoverBrush"]=Brush(Dark?"#314151":"#E6F2F0");Resources[SystemColors.WindowBrushKey]=Brush(Surface);Resources[SystemColors.WindowTextBrushKey]=Brush(Text);Resources[SystemColors.ControlBrushKey]=Brush(Surface);Resources[SystemColors.ControlTextBrushKey]=Brush(Text);Resources[SystemColors.HighlightBrushKey]=Brush("#087F72");ControlStyles();Appearance.ApplyCaption(this,Dark);list.Background=Brush(Surface);list.BorderBrush=Brush(Line);changes.Foreground=Brush(Text);sidePanel.Background=Brush(Surface);sidePanel.BorderBrush=Brush(Line);empty.Foreground=Brush(Muted);status.Foreground=Brush(Muted);position.Foreground=Brush(Muted);summary.Foreground=Brush(Dark?"#F5D07B":"#946200");SetChangePanelVisibility();Refresh();map.InvalidateVisual();}
  void Screenshot(string file){UpdateLayout();var b=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(this);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(file))encoder.Save(f);}
  async Task Smoke(string dir){
   Directory.CreateDirectory(dir);await Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);await Task.Delay(500);
   if(Result==null){File.WriteAllText(Path.Combine(dir,"ui-failed.txt"),"Comparison failed");Application.Current.Shutdown(2);return;}
   var checks=new List<string>();
   Reports.Save(Result,Path.Combine(dir,"UI对比报告.docx"),false);Reports.Save(Result,Path.Combine(dir,"UI对比报告.html"),false);
   Screenshot(Path.Combine(dir,"UI初始.png"));
   Navigate(1);if(!(list.SelectedItem is DisplayRow)||((DisplayRow)list.SelectedItem).Row.Kind==ChangeKind.Same)throw new Exception("差异导航失败");checks.Add("PASS 下一差异导航");
   search.Text="电导率";Find();if(!(list.SelectedItem is DisplayRow)||!((DisplayRow)list.SelectedItem).Row.Preview.Contains("电导率"))throw new Exception("搜索定位失败");checks.Add("PASS 中文搜索定位");search.Text="";
   only.IsChecked=true;Refresh();if(visible.Count!=Result.Changes)throw new Exception("仅差异筛选失败");checks.Add("PASS 仅显示差异");
   await Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Screenshot(Path.Combine(dir,"UI仅差异.png"));
   zoom.SelectedIndex=2;if(Math.Abs(Zoom-1.2)>.01)throw new Exception("缩放失败");checks.Add("PASS 120%缩放");
   dark.IsChecked=true;Theme();await Dispatcher.InvokeAsync(()=>{},DispatcherPriority.ApplicationIdle);Screenshot(Path.Combine(dir,"UI暗黑模式.png"));checks.Add("PASS 暗黑模式渲染");
   dark.IsChecked=false;zoom.SelectedIndex=1;Theme();
   string oldLeft=leftPath.Text;leftPath.Text=rightPath.Text;rightPath.Text=oldLeft;await Run();checks.Add("PASS 左右交换后重新对比");
   File.WriteAllLines(Path.Combine(dir,"ui-result.txt"),checks.Concat(new[]{Reports.Summary(Result),"Visible="+visible.Count,"Total="+Result.Rows.Count,"ReadOnly=True"}),new UTF8Encoding(true));
   Application.Current.Shutdown(0);
  }
 }
 public static class Program {
  [STAThread] public static int Main(string[] args){try{if(args.Length>=4&&args[0]=="--report"){var c=DiffEngine.Compare(DocxReader.Load(args[1],CancellationToken.None),DocxReader.Load(args[2],CancellationToken.None),new CompareOptions(),CancellationToken.None);Reports.Save(c,args[3],false);return 0;}var app=new Application();app.DispatcherUnhandledException+=(s,e)=>{MessageBox.Show(e.Exception.Message,"Word_Compare 错误");e.Handled=true;};return app.Run(new MainWindow(args));}catch(Exception e){if(args.Contains("--report")){File.WriteAllText(Path.Combine(Path.GetTempPath(),"Word_Compare_last_error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"Word_Compare 启动失败");return 1;}}
 }
}
